<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class UserController extends Controller { public function index(){return view('admin.users.index');} public function data(){return response()->json(['data'=>User::latest()->get()]);} public function show(User $user){return response()->json($user);} public function store(Request $r){$v=$r->validate(['name'=>'required|max:120','email'=>'required|email|unique:users,email','password'=>'required|min:8|confirmed','role'=>'required|in:admin,hr','status'=>'required|in:active,inactive']);User::create($v);return response()->json(['message'=>'User account added successfully.']);} public function update(Request $r,User $user){$v=$r->validate(['name'=>'required|max:120','email'=>['required','email',Rule::unique('users')->ignore($user->id)],'password'=>'nullable|min:8|confirmed','role'=>'required|in:admin,hr','status'=>'required|in:active,inactive']);if(empty($v['password']))unset($v['password']);$user->update($v);return response()->json(['message'=>'User account updated successfully.']);} public function destroy(User $user){if($user->is(auth()->user()))return response()->json(['message'=>'You cannot delete your own account.'],422);$user->delete();return response()->json(['message'=>'User account deleted successfully.']);} }
